\end{align*}

\label{thm:h_k=H_k}
For any weighted graph $\tilde G=(\tilde V,\tilde E,\tilde\mu,\tilde w)$ with $n$ vertices, for any $k\in\{1,2,\cdots,n\}$, we have \[h_k(\tilde G)\ge \ell_k(\tilde G)\ge \underline{\ell_k}(\tilde G).\] 
For any weighted forest $G=(V,E,\mu,w)$ with $n$ vertices, we must have \[h_k(G)= \ell_k(G)= \underline{\ell_k}(G).\]

All of them are obtained by a \emph{minimax} procedure:
\begin{equation}\label{eq:continuous}
\lambda_k^{\mathrm{ind}}(\Delta_p):=\inf_{\substack{S\text{ origin-symmetric, compact}\\\mathrm{ind}(S)\ge k}}~\sup_{f\in S}\frac{\int_\Omega|\nabla f(z)|^pdz}{\int_\Omega|f(z)|^pdz}
\end{equation}
where $\mathrm{ind}(\cdot)$ is an admissible index for origin-symmetric compact subsets of the Sobolev space $H_0^1(\Omega)$.

Let 
\begin{equation}\label{eq:discrete}
\lambda_k^{\mathrm{ind}}(\Delta_p):=\inf_{\substack{S\text{ origin-symmetric, compact}\\\mathrm{ind}(S)\ge k}}~\max_{x\in S}\frac{\sum\limits_{u\sim v}w_{uv}|x_u-x_v|^p}{\sum\limits_v\mu_v|x_v|^p} 
\end{equation}
be the min-max eigenvalue of $\Delta_p$ on a graph $G=(V,E,\mu,w)$, and let
\begin{equation}\label{eq:discrete/maxmin}
\underline{\lambda_k^{\mathrm{ind}}}(\Delta_p):=\sup_{\substack{S\text{ origin-symmetric, compact}\\\mathrm{ind}(S)\ge k}}~\min_{x\in S}\frac{\sum\limits_{u\sim v}w_{uv}|x_u-x_v|^p}{\sum\limits_v\mu_v|x_v|^p} 
\end{equation}
be the max-min eigenvalue of $\Delta_p$ on $G=(V,E,\mu,w)$ with $n$ vertices.

\label{thm:1-Lap=h}
Let $\Delta_1$ denote the 1-Laplacian of a forest $G$ with $n$ vertices. Then, for any admissible index, for any $k$, we have the equality
\begin{align*}
h_k(G)=\lambda_k^{\mathrm{ind}}(\Delta_1)=\underline{\lambda_k^{\mathrm{ind}}}(\Delta_1).
\end{align*}

\label{cor:minmax-indepen-index}
Let $\Delta_1$ denote the 1-Laplacian of a forest. Then, for any $k$, 
$$ \lambda_k^{\gamma}(\Delta_1)=\lambda_k^{\gamma^+}(\Delta_1) =\lambda_k^{\textrm{Y-ind}}(\Delta_1).$$

\label{cor:tree-p-Lap}
For any weighted forest $G$ satisfying $\mu_v=\sum_{u\in V:u\sim v}w_{uv}$, $\forall v\in V$, for any $p\ge 1$, we have
$$\frac{2^{p-1}}{p^p}h_k(G)^p\le \lambda_{k}(\Delta_p)\le 2^{p-1} h_k(G).$$

\label{thm:beta-p}
For any weighted graph $G=(V,E,\mu,w)$ satisfying $\mu_v=\sum_{u\in V:u\sim v}w_{uv}$, $\forall v\in V$, for any $p\ge 1$, we have 
$$\frac{2^{p-1}}{p^p}h_{k-\beta}(G)^p\le \lambda_{k}(\Delta_p)\le 2^{p-1} h_k(G).$$

Due to its overwhelming length, we divide our proof into several steps.

\vspace{0.3cm}

\noindent\underline{Step 1. Setup.}
\newline\noindent For ease of presentation, we prove the case when $G$ is a weighted tree, whereas the proof for the general case of weighted forests is done by mimicking the following proof. Let \[S_1:=arg\,min_{\mathcal A=(A_1,\dots,A_k)\in\mathcal{P}_k(V)}~\max_{1\le i\le k}\phi(A_i)\] be the set of all subpartitions that minimize the maximum $\phi$-value among the subsets. For reasons that will become clear later, we do not attempt to start working on a subpartition in $S_1$. Instead, we need more requirements on the subpartitions than that and furthur refine our desired class by letting \[S_2:=arg\,min_{\mathcal A=(A_1,\dots,A_k)\in S_1}f(\mathcal A),\] where \[f(\mathcal A)=|\{1\le i\le k\colon\phi(A_i)=h_k\}|,\] be the set of all subpartitions in $S_1$ minimizing the number of subsets sharing the maximum $\phi$-value and \[S_3:=arg\,min_{\mathcal A=(A_1,\dots,A_k)\in S_2}~\sum_{i=1}^k\mu(A_i)\] be the set of all subpartitions in $S_2$ that minimize the total weighted degree. Now, pick any subpartition $\mathcal A=(A_1,\dots,A_k)\in S_3$. By reordering if necessary, suppose that \[\phi(A_1)\le\dots\le\phi(A_k)=h_k\] without loss of generality.

\vspace{0.3cm}

\noindent\underline{Step 2. Achieving pairwise nonadjacency.}
\newline\noindent We prove that there exists $v_1\in A_1,\dots,v_{k-1}\in A_{k-1}$ such that \[A_1\setminus\{v_1\},\dots,A_{k-1}\setminus\{v_{k-1}\},V\setminus(A_1\cup\dots\cup A_{k-1})\] are pairwise nonadjacent in this step.

Indeed, since $\mathcal A=(A_1,\dots,A_k)\in S_3$, each $A_i$ is connected. (This is because otherwise, if some $A_j$ is not connected, then we write \[A_j=A_{j1}\cup\dots\cup A_{jm},\] where $A_{j1},\dots,A_{jm}$ are the $m$ connected components of $A_j$. Now, by Lemma \ref{lemma:basic-phi}, since \[E(A_{j1},A_{j2}\cup\dots\cup A_{jm})=\varnothing,\] we have \[\min\{\phi(A_{j1}),\phi(A_{j2}\cup\dots\cup A_{jm})\}\le\phi(A_j).\] If it happens that $\phi(A_{j1})>\phi(A_j)$, then we apply Lemma \ref{lemma:basic-phi} and the same procedure on \[A_{j2}\cup\dots\cup A_{jm}=A_{j2}\cup(A_{j3}\cup\dots\cup A_{jm}),\] and eventually we will obtain some $1\le p\le m$ such that $\phi(A_{jp})\le\phi(A_j)$. Now note that the subpartition \[\tilde{\mathcal A}=(A_1,\dots,A_{jp},\dots,A_k)\] is in $S_1$, since replacing by $A_j$ by $A_{jp}$ does not increase the maximum $\phi$-value. For this same reason, we can infer that $\tilde{\mathcal A}\in S_2$ as well. However, the total weighted degree of $\tilde{\mathcal A}$ is smaller than that of $\mathcal A$, which contradicts the assumption that $\mathcal A\in S_3$. Therefore, each $A_i$ is connected.) Now, recall that the graph $G$ we are working on is assumed to be a tree, so we can make the $k$ connected subsets $A_1,\dots,A_k$ pairwise nonadjacent by removing a vertex in each of some $k-1$ subsets. (See Figure \ref{fig:pairwisenonadj}).



