\vspace{0.3cm}

\noindent\underline{Step 3. Showing $h(V\setminus(A_1\cup\dots\cup A_{k-1}))=h_k(G)$.}
\newline\noindent Firstly, note that we have \[h(V\setminus(A_1\cup\dots\cup A_{k-1}))\le h_k(G).\] Indeed, since \[A_k\subseteq V\setminus(A_1\cup\dots\cup A_{k-1}),\] we have \[h(V\setminus(A_1\cup\dots\cup A_{k-1}))=\min_{C\subseteq V\setminus(A_1\cup\dots\cup A_{k-1})}\phi(C)\le\phi(A_k)=h_k(G).\]

Next, for the sake of contradiction, we suppose that $h(V\setminus(A_1\cup\dots\cup A_{k-1}))<h_k(G)$. Then, by the definition of $h$, there is some $A_k'\subseteq V\setminus(A_1\cup\dots\cup A_{k-1})$ such that \[\phi(A_k')=h(V\setminus(A_1\cup\dots\cup A_{k-1}))<h_k(G).\] Then, we can replace $A_k$ by $A_k'$ and consider the subpartition \[\mathcal A':=(A_1',\dots,A_{k-1}',A_k'):=(A_1,\dots,A_{k-1},A_k'),\] where $A_i':=A_i$ for $1\le i\le k-1$. We divide into two cases:

\vspace{0.3cm}

\noindent\textsl{Case 1.} $\phi(A_{k-1})=\phi(A_k)=h_k(G)$.
\newline Then, $f(\mathcal A')=f(\mathcal A)-1<f(\mathcal A)$ contradicts the assumption that $\mathcal A\in S_3\subseteq S_2$.

\vspace{0.3cm}

\noindent\textsl{Case 2.} $\phi(A_{k-1})<\phi(A_k)=h_k(G)$.
\newline Then, \[\max_{1\le i\le k}\phi(A_i')=\max\{\phi(A_{k-1}),\phi(A_k')\}<h_k(G)\] contradicts the assumption that $\mathcal A\in S_3\subseteq S_1$.

\vspace{0.3cm}

Therefore, we must have $h(V\setminus(A_1\cup\dots\cup A_{k-1}))=h_k(G)$. 

\vspace{0.3cm}

\noindent\underline{Step 4. Showing $h(A_i\setminus\{v_i\})\ge h_k(G)\text{ for any }1\le i\le k-1\text{ such that }A_i\setminus\{v_i\}\ne\varnothing$.}
\newline\noindent Suppose on the contrary that, for some $1\le j\le k-1$, $h(A_j\setminus\{v_j\})<h_k$. Then, by the definition of $h(\cdot)$, there exists a subset $\overline A_j\subseteq A_j\setminus\{v_j\}$ such that $h_k(G)>h(A_j\setminus\{v_j\})=\phi(\overline A_j)$ we can replace the subpartition $\mathcal A$ by \[\overline{\mathcal A}=(A_1,\dots,\overline A_j,\dots,A_k)\in S_2.\] Note that $\overline{\mathcal A}\in S_1$ because the $\phi$-value of each of the $k$ subsets in $\mathcal A$ does not exceed $h_k(G)$. Also, $\overline{\mathcal A}\in S_2$ because $f(\overline{\mathcal A})$ either equals $f(\mathcal A)$ or $f(\mathcal A)-1$ (when $\phi(A_j)<h_k$ or $\phi(A_j)=h_k$, respectively). However, we have $\mu(\overline{\mathcal A})=\mu(\mathcal A)-\mu_{v_j}<\mu(\mathcal A)$. This contradicts the assumption that $\mathcal A\in S_3$.

\vspace{0.3cm}

\noindent\underline{Step 5. Showing $\underline{\ell_k}(G)\ge h_k(G)$ for any weighted tree $G$.}
\newline\noindent Indeed, we have
\begin{center}\begin{align}\underline{\ell_k}(G)&=\max_{A\subseteq V,~|A|=n-k+1}h(A)\notag
\\&\ge h(V\setminus\{v_1,\dots,v_{k-1}\})\notag
\\&=\min\{h(V\setminus(A_1\cup\dots\cup A_{k-1})),h(A_i\setminus\{v_i\})\colon 1\le i\le k-1,A_i\setminus\{v_i\}\ne\varnothing\}\label{eq:h-decompose}
\\&=h(V\setminus(A_1\cup\dots\cup A_{k-1}))\label{eq:hgehk}
\\&=h_k(G),\notag\end{align}\end{center}
where the equality \eqref{eq:h-decompose} is based on {Lemma \ref{lem:cheeger-set-disjoint}} and the pairwise-nonadjacency of the $k$ subsets, and the equality \eqref{eq:hgehk} is due to the result proved in the last step.

\vspace{0.3cm}

\noindent\underline{Step 6. Sketch for the general case when $G$ is a weighted forest.}
\newline\noindent We can actually apply the same idea as above. Namely, pick a subpartition from $S_3$ and remove $v_1\dots,v_{k-1}$ in order to achieve the pairwise nonadjacency. If there are some remaining quotas of the $k-1$ quotas, we can safely remove any vertices that are unrelated to the subgraph that achieves the minimum $\phi$-value.



\vspace{0.3cm}

\noindent\underline{Step 7. Showing $h_k(\tilde G)\ge\ell_k(\tilde G)$ for any weighted graph $\tilde G=(\tilde V,\tilde E,\tilde\mu,\tilde w)$.}
\newline\noindent It suffices to show that for any subpartitions $(A_1,\dots,A_k)$ and $(B_1,\dots,B_{n-k+1})$ of $\tilde V$, we have \[\max_{1\le i\le k}\phi(A_i)\ge\min_{B\in \mathcal{U}(B_1,\cdots,B_{n-k+1})}\phi(B).\] Let $|\tilde V|=n$, apply Lemma \ref{lem:pigeonhole} to take the desired common union $C$. Note that the induced subgraph is connected, so the minimum on the right side is attained by $C$, while the maximum on the left side is attained by some ``worst'' connected component of the induced subgraph of $C$, whose $\phi$-value must not be less than that of the induced subgraph.

\vspace{0.3cm}

\noindent\underline{Step 8. Conclusion.}
\newline\noindent Since it is obvious that $\ell_k(\tilde G)\ge\underline{\ell_k}(\tilde G)$ for any weighted graph $\tilde G$, the proof is established.

